import * as E from './engine.js';
import * as I from './importers.js';
const STORAGE='pitocuna.production.v3', ARCHIVE='pitocuna.previous.v3';
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>v===null||v===undefined||!Number.isFinite(v)?'No calculable':new Intl.NumberFormat('es-PE',{maximumFractionDigits:2}).format(v);
const date=d=>d?d.split('-').reverse().join('/'):'Sin fecha';
const fmtPercent=v=>v===null?'No aplica':num(v)+' %';
const badge=(text,tone='')=>`<span class="badge ${tone}">${esc(text)}</span>`;
const tone=r=>r==='Bloqueada'?'red':r==='Por confirmar'?'amber':r==='Terminada'?'gray':'';
const button=(action,text,id='',style='ghost')=>`<button class="${style}" data-action="${action}" data-id="${esc(id)}">${esc(text)}</button>`;
const empty=(title,body)=>`<div class="empty"><b>${title}</b>${body}</div>`;
const notice=(text,type='')=>`<div class="notice ${type}">${text}</div>`;
const table=(heads,rows,cls='data-table')=>`<div class="overflow"><table class="${cls}"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const heading=(n,title,description,actions='')=>`<div class="heading"><div><div class="eyebrow">${n} / Producción LPS + LBMS</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;
const cell=(label,value)=>`<div class="detail-cell"><small>${label}</small>${value}</div>`;
const stat=(label,value,note)=>`<div class="stat"><span>${label}</span><strong>${value}</strong><span>${note}</span></div>`;
const option=(value,label,selected)=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const activityOption=(a,selected)=>option(a.id,`${a.id} · ${a.name} / ${a.location||'sin ubicación'}`,selected);
const formEnd=(label='Guardar')=>`<div class="form-actions"><button type="button" class="ghost" data-action="close">Cancelar</button><button class="button" type="submit">${label}</button></div></form>`;
let state, storageFailure=false;
try{const saved=localStorage.getItem(STORAGE);state=saved?E.validateBackup(JSON.parse(saved)):E.demoState();if(!saved)localStorage.setItem(STORAGE,JSON.stringify(state));}catch(e){state=E.demoState();storageFailure=true;}
let view='inicio',dataTab='cronograma',weeks=6,filterStatus='todos',group='',chosenPlan='',advanceTab='esquema',pendingImport=null,toastTimer;
function toast(message,error=false){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.toggle('error',error);$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function modal(title,html){$('modal-title').textContent=title;$('modal-body').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function commit(action,detail,fn,close=true){const old=E.clone(state);try{fn();E.validateBackup(state);E.audit(state,action,detail);localStorage.setItem(STORAGE,JSON.stringify(state));storageFailure=false;if(close)$('modal').close();render();toast('Guardado en este navegador');return true;}catch(e){state=old;toast(e.message,true);return false;}}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){download('pitocuna-respaldo.json',JSON.stringify(state,null,2),'application/json');}
function selectedPlan(){return state.plans.find(p=>p.id===chosenPlan)||state.plans.at(-1);}
function currentModel(){return E.compute(state);}
function activityLink(a){return `<button class="link-button" data-action="activity" data-id="${esc(a.id)}">${esc(a.id)}</button><b>${esc(a.name)}</b><small>${esc(a.code)} · ${esc(a.location||'Sin ubicación')}</small>`;}
function startPage(model){
 const ready=state.activities.filter(a=>E.readiness(state,a,model).ready).length,unlinked=state.activities.filter(a=>E.durationOf(state,a)===null).length,pending=state.restrictions.filter(r=>!E.isReleased(r,state.project.cut));
 const steps=[['datos','1','Cargar datos','Cronograma + ubicación + metrados y rendimientos'],['lookahead','2','Preparar el trabajo','Revisar próximas semanas y condiciones de inicio'],['restricciones','3','Liberar restricciones','Responsable, fecha necesaria, evidencia y revisión'],['semanal','4','Acordar compromisos','Solo trabajo preparado; congelar el plan'],['avance','5','Registrar y aprender','Avance por ubicación, PPC, PRL y continuidad']];
 return heading('INICIO','Del cronograma al trabajo preparado','Los datos de obra alimentan la preparación, los compromisos y el flujo por ubicación. Cada salida se puede reconstruir desde sus registros.',button('go-data','Cargar cronograma y metrados','','button'))+
 `<div class="stats">${stat('Actividades localizadas',state.activities.filter(a=>a.location).length,`${state.activities.length} actividades en el cronograma`)}${stat('Datos por completar',unlinked,'Sin metrado o rendimiento calculable')}${stat('Restricciones abiertas',pending.length,'Una estimación no confirma la liberación')}${stat('Actividades preparadas',ready,'Con revisión de preparación vigente')}</div>`+
 `<section class="panel"><div class="panel-header"><h2>Así funciona el modelo de tu tesis</h2>${badge('Actividad · ubicación · tiempo')}</div><div class="steps">${steps.map(([url,n,title,body])=>`<a href="#${url}" class="step"><span class="n">${n.padStart(2,'0')}</span><b>${title}</b><p>${body}</p></a>`).join('')}</div>${notice('El cronograma conserva sus fechas de referencia. El plan operativo calcula <b>d = Q / R</b>; las restricciones y las precedencias condicionan el pronóstico. Solo el trabajo revisado entra al compromiso semanal.')}</section>`+
 `<div class="grid2"><section class="panel"><div class="panel-header"><h2>Próximas decisiones</h2><a href="#lookahead" class="link-button">Abrir Lookahead</a></div><ul class="status-list">${E.lookahead(state,weeks,model).slice(0,5).map(a=>{const r=E.readiness(state,a,model);return `<li><div class="actions">${activityLink(a)}${badge(r.state,tone(r.state))}</div><small class="muted">${esc(r.reasons[0]||'Disponible para acordar su compromiso')}</small></li>`;}).join('')||'<li>Carga un cronograma para comenzar.</li>'}</ul></section><section class="panel"><h2>Datos con contexto</h2>${state.project.mode==='demo'?notice('<b>Escenario de prueba.</b> Las 8 actividades, cantidades y fechas son ficticias. Al importar tus archivos se iniciará un proyecto propio sin mezclar los ejemplos.','warning'):notice('<b>Proyecto propio.</b> Conserva la fuente y versión de tus registros; exporta respaldos periódicos.')}<p class="small muted">El residente o responsable de producción revisa las condiciones y decide qué trabajo comprometer. La ausencia de alertas no sustituye esa revisión.</p><div class="actions">${button('template-schedule','Plantilla cronograma CSV')}${button('template-measures','Plantilla metrados CSV')}</div></section></div>`;
}
function dataPage(model){
 const tabs=[['cronograma','Cronograma'],['metrados','Metrados y rendimientos'],['ubicaciones','Ubicaciones LBS'],['calendario','Proyecto y calendario']];
 let body='';
 if(dataTab==='cronograma')body=`<div class="panel-header"><h2>Actividades del cronograma</h2><div class="actions">${button('import-schedule','Importar XML / Excel / CSV','','button')}${button('edit-activity','Añadir actividad')}${button('template-schedule','Descargar plantilla')}<a class="ghost" href="ejemplos/datos-ejemplo.xlsx" download>Excel de ejemplo</a><a class="ghost" href="ejemplos/cronograma-ejemplo.xml" download>XML de ejemplo</a></div></div>${notice('Importa <b>MS Project XML</b> o una hoja Excel/CSV. Conservamos ID, partida, fechas y precedencias. Una tarea XML sin ubicación debe localizarse antes de preparar su ejecución.')}`+
 (state.activities.length?table(['Actividad / partida','LBS / cuadrilla','Referencia del cronograma','Metrados vinculados','Revisar'],state.activities.map(a=>{const m=E.measureOf(state,a),r=model.rows.get(a.id);return `<tr><td>${activityLink(a)}<small>${esc(a.source)}</small></td><td>${esc(a.component)}<small>${esc(a.flowGroup||'Sin grupo LBMS')} · ${esc(a.crew||'Sin cuadrilla')}</small></td><td>${date(a.start)} → ${date(a.finish)}<small>Predecesoras: ${esc(a.predecessors.join(', ')||'Ninguna')}</small></td><td>${m?`${num(m.quantity)} ${esc(m.unit)} · ${num(m.rate)} ${esc(m.rateUnit)}/j`:'Sin vincular'}<small>${r.issues.length?esc(r.issues.join(' · ')):num(r.duration)+' jornadas calculadas'}</small></td><td>${button('edit-activity','Editar',a.id)} ${button('edit-measure','Metrado',a.id)}</td></tr>`;})):empty('Comienza por tu cronograma','Carga un archivo o añade una actividad manualmente.'));
 if(dataTab==='metrados')body=`<div class="panel-header"><h2>Cantidad y capacidad de producción</h2><div class="actions">${button('import-measures','Importar Excel / CSV','','button')}${button('import-rates','Cargar catálogo APU CSV')}${button('edit-measure','Añadir metrado')}${button('template-measures','Descargar plantilla')}<a class="ghost" href="ejemplos/datos-ejemplo.xlsx" download>Excel de ejemplo</a></div></div>${notice('Los rendimientos APU son referencias; deben validarse con las cuadrillas de obra. El catálogo CSV exige coincidencia de código, descripción y unidad. La unión con el cronograma se hace por <b>código de partida + ubicación</b>, nunca solo por el nombre. Registra cantidades y rendimientos por frente; <b>unidad del rendimiento</b> significa la cantidad producida por jornada.')}`+
 (state.measures.length?table(['Partida / ubicación','Metrado Q','Rendimiento R','d = Q/R','Fuente / enlace',''],state.measures.map((m,i)=>{const linked=state.activities.filter(a=>E.key(a.code,a.location)===E.key(m.code,m.location)),valid=m.rate>0&&E.normalizeUnit(m.unit)===E.normalizeUnit(m.rateUnit);return `<tr><td><b>${esc(m.code)} / ${esc(m.location)}</b></td><td>${num(m.quantity)} ${esc(m.unit)}</td><td>${num(m.rate)} ${esc(m.rateUnit)}/j</td><td>${valid?num(m.quantity/m.rate)+' j':badge('No calculable','amber')}</td><td>${esc(m.source)}<small>${linked.length?linked.map(a=>esc(a.id)).join(', '):'Sin actividad asociada'}</small></td><td>${button('measure-index','Editar',String(i))}</td></tr>`;})):empty('Agrega los metrados por ubicación','La duración se calcula cuando Q, R y sus unidades son compatibles.'));
 if(dataTab==='ubicaciones'){
 const locations=[...new Set(state.activities.map(a=>a.location).filter(Boolean))];body=`<h2>Estructura de ubicaciones (LBS)</h2><p class="small muted">Distingue tramos de agua, reservorio y UBS. Los grupos LBMS reúnen ubicaciones comparables; el orden controla su representación espacial.</p>`+table(['Ubicación','Componente','Grupo de flujo / orden','Actividades'],locations.map(loc=>{const tasks=state.activities.filter(a=>a.location===loc);return `<tr><td><b>${esc(loc)}</b></td><td>${esc([...new Set(tasks.map(a=>a.component))].join(' / '))}</td><td>${esc([...new Set(tasks.map(a=>`${a.flowGroup||'Sin grupo'} / ${a.order??'Sin orden'}`))].join(' · '))}</td><td>${tasks.map(a=>activityLink(a)).join('<br>')}</td></tr>`;}));
 }
 if(dataTab==='calendario')body=`<h2>Calendario laboral y responsables</h2>${notice('Una duración en jornadas no se suma directamente como días calendario. Usa capacidad <b>0</b> para un día no laborable, <b>0,5</b> para media jornada y <b>1</b> para jornada completa. El corte corresponde al cierre del día observado.')}<form data-form="calendar"><div class="form-grid">${field('Nombre del proyecto','name',state.project.name,'text','required')}${field('Responsable que registra / revisa','operator',state.project.operator,'text','required')}${field('Origen de la escala de trabajo','origin',state.project.origin,'date','required')}<label class="field">Feriados y días no laborables adicionales<textarea name="holidays" placeholder="2026-05-01, 2026-06-29">${esc(state.project.holidays.join(', '))}</textarea></label><div class="full calendar-days">${['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'].map((d,i)=>`<label>${d}<input aria-label="Capacidad ${d}" type="number" name="day${i}" min="0" max="1" step="0.25" value="${state.project.work[i]}" required></label>`).join('')}</div><label class="check full"><input type="checkbox" name="confirmed" required ${state.project.calendarConfirmed?'checked':''}>Confirmé este calendario y su correspondencia con los datos de obra.</label></div>${formEnd('Guardar calendario')}</div>`;
 return heading('01','Datos que alimentan el modelo','Primero el cronograma; después, las cantidades, los rendimientos y las ubicaciones. Puedes importar tus archivos o completar los registros manualmente.')+(state.sourceReview?notice(esc(state.sourceReview.note),'warning'):'')+`<div class="subtabs">${tabs.map(([id,label])=>`<button data-data-tab="${id}" class="${dataTab===id?'active':''}">${label}</button>`).join('')}</div><section class="panel">${body}</section>`;
}
function lookaheadPage(model){
 const start=E.addDays(state.project.cut,1),tasks=E.lookahead(state,weeks,model).filter(a=>filterStatus==='todos'||E.readiness(state,a,model).state===filterStatus);
 const heads=Array.from({length:weeks},(_,i)=>({start:E.addDays(start,i*7),end:E.addDays(start,i*7+6)}));
 return heading('02','Lookahead · preparar el trabajo','Ventana móvil de preparación calculada desde el cronograma, las cantidades y el calendario. Los compromisos se acuerdan después de resolver y verificar las condiciones.')+
 `<section class="panel"><div class="panel-header"><div class="inline-fields"><label>Horizonte <select id="horizon">${[3,4,6,8].map(n=>option(n,n+' semanas',weeks)).join('')}</select></label><label>Preparación <select id="readiness-filter">${['todos','Bloqueada','Por confirmar','Preparada','Terminada'].map(v=>option(v,v==='todos'?'Todas':v,filterStatus)).join('')}</select></label></div>${badge(date(start)+' → '+date(heads.at(-1).end),'gray')}</div>`+
 `<div class="overflow"><table class="lookahead"><thead><tr><th>Actividad / ubicación</th><th>Q / R → duración</th><th>Preparación / exposición</th>${heads.map((w,i)=>`<th class="week">S+${i+1}<br>${date(w.start)}<br>${date(w.end)}</th>`).join('')}<th>Decisión</th></tr></thead><tbody>${tasks.map(a=>{const r=model.rows.get(a.id),ready=E.readiness(state,a,model),m=E.measureOf(state,a),s=r.s??model.cal.index(a.start),f=r.f??model.cal.end(a.finish);return `<tr><td>${activityLink(a)}<small>Inicio operativo: ${r.s===null?'No calculable':date(model.cal.date(r.s))}</small></td><td>${m?`${num(m.quantity)} ${esc(m.unit)} / ${num(m.rate)} ${esc(m.rateUnit)}/j`:'Sin metrado vinculado'}<small>d = ${num(r.duration)} jornadas</small></td><td>${badge(ready.state,tone(ready.state))}<small>E = ${num(r.exposure)} j${r.exposure===null?' · falta una estimación':''}</small><small>${esc(ready.reasons[0]||'Preparación confirmada')}</small></td>${heads.map(w=>`<td class="week">${s!==null&&f!==null&&s<model.cal.end(w.end)&&(f>s?f>model.cal.index(w.start):s>=model.cal.index(w.start))?`<div class="time-block ${ready.state==='Bloqueada'?'blocked':ready.ready?'':'pending'}">${num(Math.max(0,Math.min(f,model.cal.end(w.end))-Math.max(s,model.cal.index(w.start))))} j${r.f===null?" · referencia":""}</div>`:''}</td>`).join('')}<td><div class="actions">${button('activity','Revisar',a.id)}${button('restriction','Restricción',a.id)}${ready.state==='Por confirmar'?button('prepare','Confirmar',a.id):''}${ready.ready&&!a.milestone?button('commitment','Comprometer',a.id):''}</div></td></tr>`;}).join('')}</tbody></table></div>${!tasks.length?empty('Sin actividades en esta ventana','Revisa el corte, las fechas del cronograma y los filtros.'):''}<p class="table-note">Cuando Q/R y la secuencia son calculables, la barra muestra el plan operativo. En las demás actividades muestra solo las fechas de referencia del cronograma. El pronóstico condicionado se consulta en Avance LBMS. El trabajo atrasado sin terminar se mantiene como arrastre.</p></section>`;
}
function restrictionsPage(model){
 const states=['Abierta','En revisión','Liberada'];const status=r=>E.isReleased(r,state.project.cut)?'Liberada':r.evidence?'En revisión':'Abierta';
 return heading('03','Liberación de restricciones','Cada condición se vincula a una o varias actividades–ubicaciones. La evidencia y la revisión confirman la liberación; la fecha estimada solo alimenta las alertas.',button('restriction','Registrar restricción','','button'))+`<div class="board">${states.map(st=>{const records=state.restrictions.filter(r=>status(r)===st);return `<section class="lane"><h3>${st} · ${records.length}</h3>${records.map(r=>{const need=E.requiredDate(r),h=need&&r.estimated?model.cal.difference(need,r.estimated):null;return `<article class="ticket">${badge(r.id,st==='Liberada'?'':h===null?'blue':h<0?'red':'amber')}<h3>${esc(r.title)}</h3><p>${esc(r.category)} · ${esc(r.owner)}<br>Necesaria: ${date(need)}<br>Estimada: ${date(r.estimated)}</p><p>H = ${num(h)} jornadas${h===null?' · información incompleta':h<0?' · liberación prevista tardía':''}</p><p>${r.links.map(l=>{const a=state.activities.find(a=>a.id===l.activityId);return `${esc(l.activityId)} / ${esc(a?.location)} · ${date(l.needed)}`;}).join('<br>')}</p><div class="actions">${button('edit-restriction','Revisar',r.id)}${st!=='Liberada'?button('release','Evidencia / liberar',r.id):badge('Cierre documentado')}</div></article>`;}).join('')||'<p class="mini">Sin registros.</p>'}</section>`;}).join('')}</div>${notice('El PRL usa una sola vez cada restricción y la <b>fecha necesaria más temprana</b> de sus vínculos vigentes en el corte congelado, tal como establece el borrador. Las fechas ausentes se reportan por separado.')}`;
}
function planSelector(){const p=selectedPlan();return `<select id="plan-select" aria-label="Corte semanal">${state.plans.map(plan=>option(plan.id,`${date(plan.start)}–${date(plan.end)} · ${plan.frozenAt?'Congelado':'Borrador'}`,p?.id)).join('')}</select>`;}
function weeklyPage(model){
 const p=selectedPlan();let body=empty('Aún no hay un plan semanal','Crea una semana, incorpora actividades preparadas y congela sus compromisos.');
 if(p){const k=E.indicators(state,p);body=`<div class="panel-header"><div class="inline-fields">${planSelector()}${badge(p.frozenAt?'Plan congelado':'En preparación',p.frozenAt?'':'amber')}</div><div class="actions">${!p.frozenAt?button('choose-commitment','Añadir compromiso',p.id)+button('freeze','Congelar plan',p.id,'button'):badge('Denominador conservado')}</div></div>${notice(p.frozenAt?'Se conservaron los compromisos, el calendario, las ventanas programadas y las fechas necesarias del corte. El cierre definitivo exige registros dentro de la semana y revisión del criterio de término.':'Solo pueden incorporarse actividades preparadas, con un alcance medible y un criterio de término. La semana aún no está congelada.')}`+
 table(['Actividad / ubicación','Alcance comprometido','Criterio de término','Resultado','Acción'],p.members.map(m=>{const a=state.activities.find(a=>a.id===m.activityId);return `<tr><td>${activityLink(a)}</td><td>${num(m.target)} ${esc(m.unit)}</td><td>${esc(m.criterion)}</td><td>${badge(m.result,m.result==='incumplido'?'red':m.result==='pendiente'?'amber':'')}<small>${esc(m.cause||'')}</small></td><td>${p.frozenAt?button('close-commitment','Cerrar resultado',m.activityId):button('remove-commitment','Retirar',m.activityId)}</td></tr>`;}))+(p.frozenAt?`<div class="detail-grid">${cell('PPC del corte',fmtPercent(k.ppc))}${cell('Compromisos',`${k.fulfilled} cumplidos / ${k.committed} congelados`)}${cell('Sin evaluar',k.pending)}</div>`:'');}
 return heading('04','Plan semanal · comprometer y cumplir','Lo previsto pasa por preparación antes de convertirse en compromiso. Se conserva el plan del corte para evaluar su confiabilidad.',button('new-plan','Crear semana','','button'))+`<section class="panel">${body}</section>`;
}
function flowGraph(tasks,model){
 const locations=[...new Map(tasks.filter(a=>a.location&&Number.isFinite(a.order)).sort((a,b)=>a.order-b.order).map(a=>[a.location,a.order])).keys()];
 if(!locations.length)return empty('Falta la estructura espacial','Asigna un grupo de flujo y un orden numérico a las ubicaciones en Datos de obra.');
 const points=tasks.flatMap(a=>{const r=model.rows.get(a.id);return [r.s,r.f,r.fs,r.ff].filter(Number.isFinite);});if(!points.length)return empty('No se puede calcular el flujo','Vincula metrados, rendimientos y unidades compatibles.');
 const min=Math.min(...points),max=Math.max(...points,min+5),width=1000,height=100+locations.length*90,left=140,right=945,top=45,band=70;
 const x=v=>left+(v-min)/(max-min)*(right-left),y=(loc,fraction=0)=>top+locations.indexOf(loc)*band+fraction*band;
 const colors=['#24765b','#4a76a3','#b08742','#8b6d96','#526d79'],codes=[...new Set(tasks.map(a=>a.code))];
 let html=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Gráfico de flujo tiempo–ubicación calculado desde las actividades"><rect width="1000" height="${height}" fill="#fafbf6"/>`;
 for(let i=0;i<=6;i++){const t=min+(max-min)*i/6;html+=`<line x1="${x(t)}" y1="35" x2="${x(t)}" y2="${top+locations.length*band}" stroke="#dce5d6"/><text x="${x(t)}" y="${top+locations.length*band+25}" text-anchor="middle" font-size="10" fill="#657a67">${date(model.cal.date(t))}</text>`;}
 locations.forEach((loc,i)=>{html+=`<rect x="140" y="${y(loc)}" width="805" height="${band}" fill="${i%2?'#edf3e6':'#f7f9f0'}" opacity=".8"/><text x="120" y="${y(loc,.5)}" text-anchor="end" font-size="12" fill="#45634c">${esc(loc)}</text>`;});
 for(const [index,code]of codes.entries()){
   const color=colors[index%colors.length],series=tasks.filter(a=>a.code===code&&locations.includes(a.location)).sort((a,b)=>a.order-b.order);
   const plan=[],forecast=[];
   for(const a of series){const r=model.rows.get(a.id);if(r.s!==null&&r.f!==null)plan.push([x(r.s),y(a.location)],[x(r.f),y(a.location,1)]);if(r.fs!==null&&r.ff!==null)forecast.push([x(r.fs),y(a.location)],[x(r.ff),y(a.location,1)]);}
   const path=pts=>pts.map(([x,y],i)=>(i?'L':'M')+x+','+y).join(' ');
   if(plan.length)html+=`<path d="${path(plan)}" fill="none" stroke="${color}" stroke-width="2" stroke-dasharray="6 5" opacity=".65"/>`;
   if(forecast.length)html+=`<path d="${path(forecast)}" fill="none" stroke="${color}" stroke-width="3"/>`;
   for(const a of series){const m=E.measureOf(state,a);if(!m?.quantity)continue;const logs=state.progress.filter(p=>p.activityId===a.id&&p.date<=state.project.cut).sort((a,b)=>a.date.localeCompare(b.date));let cumulative=0;for(const p of logs){cumulative+=p.quantity;html+=`<circle cx="${x(model.cal.end(p.date))}" cy="${y(a.location,Math.min(1,cumulative/m.quantity))}" r="4" fill="${color}" stroke="white" stroke-width="1.5"><title>${esc(a.id)} · ${num(cumulative)} ${esc(m.unit)} · ${date(p.date)}</title></circle>`;}}
 }
 const cut=model.cal.end(state.project.cut);if(cut>=min&&cut<=max)html+=`<line x1="${x(cut)}" y1="30" x2="${x(cut)}" y2="${top+locations.length*band}" stroke="#b48638" stroke-dasharray="4 4"/><text x="${x(cut)}" y="22" text-anchor="middle" fill="#986e27" font-size="10">Corte</text>`;
 html+='</svg>';
 return `<div class="svg-wrap">${html}</div><div class="svg-legend">${codes.map((code,i)=>`<span><i style="--color:${colors[i%colors.length]}"></i>${esc(code)}</span>`).join('')}<span><i class="dash" style="--color:#5a745b"></i>Plan operativo</span><span>Línea sólida: pronóstico / puntos: registro observado</span></div><p class="table-note">El eje horizontal usa el calendario laboral. Las líneas conectan la misma partida entre ubicaciones ordenadas. El pronóstico es condicionado cuando hay restricciones abiertas; una estimación no confirma su liberación. Los registros son puntos medidos; no se inventa ejecución entre observaciones.</p>`;
}
function advancePage(model){
 const groups=[...new Set(state.activities.map(a=>a.flowGroup).filter(Boolean))];if(!groups.includes(group))group=groups[0]||'';
 const tasks=state.activities.filter(a=>a.flowGroup===group),locations=[...new Set(tasks.map(a=>a.location))];
 let graphic='';
 if(advanceTab==='flujo')graphic=flowGraph(tasks,model);
 else graphic=`<div class="location-cards">${locations.map(loc=>{const local=tasks.filter(a=>a.location===loc);return `<article class="location"><span class="eyebrow">${esc(local[0]?.component)}</span><h3>${esc(loc)}</h3>${local.map(a=>{const r=model.rows.get(a.id),m=E.measureOf(state,a),ready=E.readiness(state,a,model),pct=m?.quantity?Math.min(100,r.quantity/m.quantity*100):0;return `<div class="progress-card"><div class="actions">${activityLink(a)}${badge(r.done?'Entrega confirmada':r.quantity>0?'En ejecución':ready.state,tone(ready.state))}</div><p>${num(r.quantity)} / ${num(m?.quantity)} ${esc(m?.unit||'')} <b>${num(pct)} %</b></p><div class="quantity-bar"><i style="width:${pct}%"></i></div><p>Pronóstico: ${r.ff===null?'No calculable':date(model.cal.date(r.ff,true))}${r.conditional?' · condicionado':''}</p><div class="actions">${button('progress','Registrar avance',a.id)}${button('interruption','Interrupción',a.id)}</div></div>`;}).join('')}</article>`;}).join('')}</div>`;
 return heading('05','Avance y flujo por ubicación','El dibujo y el gráfico se calculan con tus actividades, cantidades, rendimientos, precedencias y registros. Redes, componentes singulares y UBS conservan sus propios grupos.',button('progress','Registrar avance','','button'))+
 `<section class="panel"><div class="panel-header"><div class="inline-fields"><label>Grupo comparable <select id="flow-group">${groups.map(g=>option(g,g,group)).join('')}</select></label></div><div class="subtabs" style="margin:0"><button data-advance-tab="esquema" class="${advanceTab==='esquema'?'active':''}">Ubicaciones y avance</button><button data-advance-tab="flujo" class="${advanceTab==='flujo'?'active':''}">Tiempo–ubicación LBMS</button></div></div>${tasks.length?graphic:empty('Sin ubicaciones para representar','Asigna grupos de flujo y orden en Datos de obra.')}</section>`+
 `<section class="panel"><h2>Plan, registro y pronóstico</h2>${table(['Actividad','Plan operativo Q/R','Ejecutado / rendimiento observado','Pronóstico condicionado','Condición'],tasks.map(a=>{const r=model.rows.get(a.id),m=E.measureOf(state,a);return `<tr><td>${activityLink(a)}</td><td>${r.s===null||r.f===null?'No calculable':date(model.cal.date(r.s))+' → '+date(model.cal.date(r.f,true))}<small>Referencia: ${date(a.start)}–${date(a.finish)}</small></td><td>${num(r.quantity)} ${esc(m?.unit)}<small>${r.rate===null?'R observado sin cobertura diaria completa; pronóstico usa R planificado':num(r.rate)+' '+esc(m?.unit)+'/j'}</small></td><td>${r.ff===null?'No calculable':date(model.cal.date(r.ff,true))}<small>${r.conditional?'Sujeto a liberación; no equivale a autorización':'Según los datos disponibles'}</small></td><td>${esc(r.issues.join(' · ')||'Datos de cálculo completos')}</td></tr>`;}))}${model.overlaps.length?notice(model.overlaps.map(o=>`${esc(o.a)} / ${esc(o.b)}: ${num(o.amount)} jornadas de solape incompatible.`).join('<br>'),'error'):''}</section>`;
}
function indicatorsPage(){
 const p=selectedPlan(),k=E.indicators(state,p),missing=state.restrictions.filter(r=>!E.requiredDate(r)).length,backlog=state.restrictions.filter(r=>E.requiredDate(r)<(p?.start||state.project.cut)&&!E.isReleased(r,state.project.cut)).length;
 return heading('06','Indicadores que se pueden reconstruir','Los indicadores nacen de compromisos, fechas y tiempos congelados por corte. Un resultado con denominador cero se muestra como “no aplica”.',button('export-report','Exportar reporte CSV'))+
 `<section class="panel"><div class="panel-header"><h2>Corte de evaluación</h2>${state.plans.length?planSelector():badge('Sin plan semanal','gray')}</div>${!p?.frozenAt?notice('Crea y congela un plan semanal para conservar los denominadores de PPC, PRL y continuidad.','warning'):notice(`${k.pending?'PPC provisional: '+k.pending+' compromiso(s) sin evaluación.':'Resultados del plan evaluado.'} Semana ${date(p.start)}–${date(p.end)}; corte observado ${date(state.project.cut)}.`)}</section>`+
 `<div class="stats">${stat('PPC',fmtPercent(k.ppc),`${k.fulfilled} cumplidos / ${k.committed} comprometidos`)}${stat('PRL',fmtPercent(k.prl),`${k.released} liberadas a tiempo / ${k.due} con fecha necesaria en el corte`)}${stat('Continuidad',fmtPercent(k.continuity),`${num(k.programmed-k.interrupted)} / ${num(k.programmed)} jornadas observadas`)}${stat('Pendientes acumuladas',backlog,`${missing} restricciones sin fecha necesaria`)}</div>`+
 `<div class="grid2"><section class="panel"><h2>Reglas de la tesis</h2><ul class="status-list"><li><b>PPC</b> = compromisos íntegramente cumplidos / compromisos congelados × 100.</li><li><b>PRL</b> = restricciones liberadas con evidencia hasta su fecha necesaria / restricciones que vencen en el periodo × 100.</li><li><b>Continuidad</b> = (tiempo programado observado − interrupciones consolidadas) / tiempo programado observado × 100.</li><li>Las interrupciones coincidentes se unen, las fechas necesarias se conservan por corte y las restricciones compartidas se cuentan una sola vez.</li></ul>${p?.frozenAt?table(['Restricción congelada','Fecha necesaria','Estado actual'],p.snapshot.restrictions.filter(r=>r.needed>=p.start&&r.needed<=p.end).map(r=>{const live=state.restrictions.find(x=>x.id===r.id);return `<tr><td>${esc(r.id)}</td><td>${date(r.needed)}</td><td>${live&&E.isReleased(live,state.project.cut)?date(live.released):'Pendiente'}</td></tr>`;}),''):''}</section><section class="panel"><h2>Trazabilidad de cambios</h2><p class="mini">Registro local de autor declarado, instante y motivo. No equivale a una bitácora institucional ni a una auditoría autenticada.</p>${state.history.slice(0,30).map(h=>`<div class="audit-row"><small>${esc(new Date(h.at).toLocaleString('es-PE'))}<br>${esc(h.actor)}</small><div><b>${esc(h.action)}</b><p>${esc(h.detail)}</p></div></div>`).join('')}<p class="mini">Se muestran los 30 cambios más recientes. El respaldo conserva todo el historial.</p></section></div>`;
}
function render(){
 const valid=['inicio','datos','lookahead','restricciones','semanal','avance','indicadores'],hash=location.hash.slice(1),aliases={panel:'inicio',board:'restricciones',field:'avance',lbms:'avance'};view=aliases[hash]||hash||'inicio';if(!valid.includes(view))view='inicio';
 document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('project-name').textContent=state.project.name;$('project-mode').textContent=state.project.mode==='demo'?'DATOS DE PRUEBA':'PROYECTO PROPIO';$('cut-date').value=state.project.cut;$('save-status').textContent=storageFailure?'Guardado local no disponible':'Guardado en este dispositivo';
 const model=currentModel(),pages={inicio:startPage,datos:dataPage,lookahead:lookaheadPage,restricciones:restrictionsPage,semanal:weeklyPage,avance:advancePage,indicadores:indicatorsPage};
 $('main').innerHTML=(storageFailure?notice('No se pudo recuperar o guardar el proyecto. Exporta un respaldo y revisa el almacenamiento del navegador.','error'):'')+pages[view](model);
}
