function interruptionForm(id){modal('Interrupción observada del frente',`<form data-form="interruption"><div class="form-grid"><label class="field full">Actividad / ubicación<select name="activityId">${state.activities.map(a=>activityOption(a,id)).join('')}</select></label>${field('Primer día de interrupción','start',state.project.cut,'date',`required max="${state.project.cut}"`)}${field('Último día de interrupción (incluido)','end',state.project.cut,'date',`required max="${state.project.cut}"`)}${field('Causa y evidencia del intervalo','cause','','text','required')}</div>${notice('Los intervalos coincidentes se consolidan. Para continuidad solo cuenta su intersección con el tiempo programado congelado y ya observado; no se descuentan días no laborables.')}${formEnd('Registrar interrupción')}</div>`);}
function templates(type){
 if(type==='schedule')download('plantilla-cronograma.csv',I.csv([['id','codigo_partida','actividad','ubicacion','componente','grupo_flujo','orden_ubicacion','inicio','fin','predecesoras','cuadrilla'],['EX-01','EXC','Excavación de zanja','T-01','Red de agua','Red principal',1,'2026-05-04','2026-05-08','','Excavación'],['TU-01','TUB','Instalación de tubería','T-01','Red de agua','Red principal',1,'2026-05-11','2026-05-14','EX-01','Tubería']]),'text/csv;charset=utf-8');
 else download('plantilla-metrados.csv',I.csv([['codigo_partida','ubicacion','metrado','unidad','rendimiento','unidad_rendimiento','fuente'],['EXC','T-01',100,'m',20,'m','Ejemplo; reemplazar con fuente autorizada'],['TUB','T-01',100,'m',25,'m','Ejemplo; reemplazar con fuente autorizada']]),'text/csv;charset=utf-8');
}
async function readImport(file,type){
 if(!file)return;if(file.size>8*1024*1024)throw Error('Máximo 8 MB por archivo; divide la información por fase.');
 if(file.name.startsWith('~$'))throw Error('Este archivo es el bloqueo temporal de Excel. Selecciona el libro original sin ~$ en el nombre.');
 if(type==='rates'){pendingImport={file:file.name,type:'measures',rateCatalog:true,rateTable:I.parseCSV(await file.text())};importPreview();return;}
 let sheets,xml=null;
 if(file.name.toLowerCase().endsWith('.xml')){if(type!=='schedule')throw Error('El XML es para el cronograma, no para metrados');xml=I.parseProjectXML(await file.text());}
 else if(file.name.toLowerCase().endsWith('.xlsx')){const {readWorkbook}=await import('./vendor/excel-reader.js');sheets=(await readWorkbook(await file.arrayBuffer())).map(sheet=>({name:sheet.sheet,data:sheet.data}));}
 else if(file.name.toLowerCase().endsWith('.csv'))sheets=[{name:file.name,data:I.parseCSV(await file.text())}];
 else throw Error('Formato admitido: .xlsx, .csv y MS Project .xml. Convierte .mpp a XML desde MS Project.');
 pendingImport={file:file.name,type,sheets,xml,sheet:0,header:0,mapping:null};
 if(type==='measures'&&sheets){const first=sheets.findIndex(s=>I.engineeringHeader(s.data));if(first>=0)pendingImport.sheet=first;}
 importPreview();
}
function importPreview(){
 const p=pendingImport;let result,html='';
 if(p.rateCatalog)result=I.matchRateCatalog(state.measures,p.rateTable,p.file);
 else if(p.xml)result=p.xml;
 else{
   const sheet=p.sheets[p.sheet],engineering=p.type==='measures'&&I.engineeringHeader(sheet.data);
   p.engineering=Boolean(engineering);
   if(engineering){
     p.location ??=p.file.replace(/\.xlsx$/i,'')+' / '+sheet.name;
     result=I.engineeringRows(sheet.data,{sheet:sheet.name,source:p.file,location:p.location});
     html=`<div class="inline-fields"><label>Hoja <select id="import-sheet">${p.sheets.map((s,i)=>option(i,s.name,p.sheet)).join('')}</select></label><label>Ubicación / alcance del TOTAL <input id="import-location" value="${esc(p.location)}"></label></div>`+notice(`<b>Metrado de expediente detectado.</b> Encabezado en fila ${engineering.header+1}. Se importa únicamente la hoja seleccionada; las otras se revisan por separado.`);
   }else{
   const rows=sheet.data.slice(p.header);if(!rows.length)throw Error('Hoja vacía');const headers=rows[0];p.mapping ||= I.suggestMapping(headers,p.type);
   result=I.mappedRows(rows,p.mapping,p.type,p.file);
   html=`<div class="inline-fields"><label>Hoja <select id="import-sheet">${p.sheets.map((s,i)=>option(i,s.name,p.sheet)).join('')}</select></label><label>Fila de encabezados <input type="number" id="import-header" min="1" max="100" value="${p.header+1}"></label></div><div class="import-map">${I.fields[p.type].map(([field,label,required])=>`<label class="field">${label}${required?' *':''}<select data-import-field="${field}">${option(-1,'No asignada',p.mapping[field])}${headers.map((h,i)=>option(i,String(h??'')||'Columna '+(i+1),p.mapping[field])).join('')}</select></label>`).join('')}</div>`;
   }
 }
 p.preview=result;
 const existing=p.type==='schedule'?state.activities:state.measures,updates=result.rows.filter(r=>existing.some(x=>p.type==='schedule'?x.id===r.id:E.key(x.code,x.location)===E.key(r.code,r.location))).length;
 html+=notice(`${result.rows.length} filas válidas · ${result.errors.length} errores · ${updates} identificadores existentes. <b>No se modifica nada hasta confirmar.</b>`);
 if(state.project.mode==='demo')html+=notice('Al confirmar se iniciará un proyecto propio y se retirarán los datos de ejemplo. El escenario anterior se conservará como respaldo local.','warning');
 else if(updates)html+=notice('Los identificadores coincidentes se actualizarán. Los compromisos y las fechas ya congelados permanecerán intactos.','warning');
 if(result.warnings)html+=result.warnings.map(t=>notice(esc(t),'warning')).join('');
 if(result.errors.length)html+=`<ul class="import-errors">${result.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`;
 html+=table(p.type==='schedule'?['ID / partida','Actividad','Ubicación','Fechas']:['Partida','Ubicación','Cantidad','Rendimiento'],result.rows.slice(0,15).map(r=>p.type==='schedule'?`<tr><td>${esc(r.id)} / ${esc(r.code)}</td><td>${esc(r.name)}</td><td>${esc(r.location)||'Pendiente de asignar'}</td><td>${date(r.start)}–${date(r.finish)}</td></tr>`:`<tr><td>${esc(r.code)}</td><td>${esc(r.location)}</td><td>${num(r.quantity)} ${esc(r.unit)}</td><td>${num(r.rate)} ${esc(r.rateUnit)}/j</td></tr>`),'');
 html+=`<p class="mini">Vista de las primeras 15 filas. Se importarán todas las filas válidas solo si no hay errores. Fechas ISO o dd/mm/aaaa; cantidades sin separador de miles.</p><div class="form-actions">${button('close','Cancelar')}${button('confirm-import','Confirmar importación','','button')}</div>`;
 modal('Revisar importación · '+p.file,html);
}
function confirmImport(){
 const p=pendingImport;if(!p?.preview.rows.length||p.preview.errors.length)throw Error('Corrige los errores del archivo antes de importar');
 if(!p.xml&&!p.engineering&&!p.rateCatalog&&I.fields[p.type].some(([field,,required])=>required&&p.mapping[field]<0))throw Error('Asigna todas las columnas obligatorias');
 const ok=commit('Importación de '+(p.type==='schedule'?'cronograma':'metrados'),`${p.file}: ${p.preview.rows.length} registros.`,()=>{
   if(state.project.mode==='demo'){localStorage.setItem(ARCHIVE,JSON.stringify(state));const oldProject=state.project;state=E.emptyState();state.project={...oldProject,mode:'propio',name:'Proyecto · '+p.file.replace(/\.[^.]+$/,'')};}
   const firstSchedule=p.type==='schedule'&&state.activities.length===0;
   if(p.type==='schedule'){
     for(const row of p.preview.rows){const i=state.activities.findIndex(a=>a.id===row.id);if(i>=0)state.activities[i]={...state.activities[i],...row};else state.activities.push(row);}
     if(p.xml)state.project.calendarConfirmed=false;
   }else{
     for(const row of p.preview.rows){const used=state.activities.filter(a=>E.key(a.code,a.location)===E.key(row.code,row.location)).some(a=>E.quantity(state,a.id)>row.quantity);if(used)throw Error('El metrado importado es menor que el avance registrado.');const i=state.measures.findIndex(m=>E.key(m.code,m.location)===E.key(row.code,row.location));if(i>=0)state.measures[i]=row;else state.measures.push(row);}
   }
   if(firstSchedule){state.project.origin=state.activities.map(a=>a.start).sort()[0];state.project.cut=E.addDays(state.project.origin,-1);}
 },true);if(ok){pendingImport=null;dataTab=p.type==='schedule'?'cronograma':'metrados';location.hash='datos';render();}
}
document.addEventListener('submit',event=>{
 const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const fd=new FormData(form),val=name=>String(fd.get(name)??'').trim(),number=name=>val(name)===''?null:Number(val(name)),yes=name=>fd.has(name),id=form.dataset.id;
 try{
  switch(form.dataset.form){
   case 'activity':commit('Actividad / ubicación',val('id'),()=>{
    const entry={id:val('id'),code:val('code'),name:val('name'),location:val('location'),component:val('component'),flowGroup:val('flowGroup'),order:number('order'),start:val('start'),finish:val('finish'),predecessors:val('predecessors').split('|').filter(Boolean).map(s=>s.trim()),crew:val('crew'),source:val('source'),incompatible:val('incompatible').split('|').filter(Boolean).map(s=>s.trim()),milestone:yes('milestone'),importIssues:[]};
    if(entry.predecessors.includes(entry.id)||entry.predecessors.some(p=>!state.activities.some(a=>a.id===p)))throw Error('Revisa los ID de las predecesoras; deben existir y ser distintos de la actividad');
    const index=state.activities.findIndex(a=>a.id===entry.id);if(!id&&index>=0)throw Error('El ID ya existe');
    if(index>=0){if(yes('reviewed'))entry.predecessorLinks=[];state.activities[index]={...state.activities[index],...entry};}else state.activities.push(entry);
    if(E.compute(state).rows.get(entry.id).issues.some(i=>i.includes('Ciclo')))throw Error('La secuencia genera un ciclo. Revisa fechas, predecesoras y cuadrilla.');
   });break;
   case 'measure':commit('Metrado / rendimiento',val('code')+' / '+val('location'),()=>{
    const entry={code:val('code'),location:val('location'),quantity:number('quantity'),unit:E.normalizeUnit(val('unit')),rate:number('rate'),rateUnit:E.normalizeUnit(val('rateUnit')).replace(/\/(jornada|dia|d|j)$/,''),source:val('source')};
    const index=state.measures.findIndex(m=>E.key(m.code,m.location)===E.key(entry.code,entry.location));
    const previous=form.dataset.index===''?null:Number(form.dataset.index);if(previous!==null&&index>=0&&previous!==index)throw Error('Ya existe otro metrado con esa partida y ubicación');
    for(const a of state.activities.filter(a=>E.key(a.code,a.location)===E.key(entry.code,entry.location)))if(E.quantity(state,a.id)>entry.quantity)throw Error('El metrado no puede quedar por debajo del avance registrado');
    if(previous!==null)state.measures[previous]=entry;else if(index>=0)state.measures[index]=entry;else state.measures.push(entry);
   });break;
   case 'calendar':commit('Calendario y responsable','Revisión de jornadas, origen y días no laborables.',()=>{
    const work=Array.from({length:7},(_,i)=>number('day'+i)),holidays=val('holidays').split(/[\s,;]+/).filter(Boolean);if(holidays.some(d=>!E.validDate(d)))throw Error('Revisa las fechas de los feriados');
    Object.assign(state.project,{name:val('name'),operator:val('operator'),origin:val('origin'),work,holidays,calendarConfirmed:yes('confirmed')});
   },false);break;
   case 'restriction':commit('Restricción',val('title'),()=>{
    const links=val('links').split('\n').filter(s=>s.trim()).map(line=>{const [activityId,needed='']=line.split(';').map(s=>s.trim());if(!state.activities.some(a=>a.id===activityId))throw Error('Actividad no encontrada: '+activityId);if(needed&&!E.validDate(needed))throw Error('Fecha necesaria inválida');return {activityId,needed:needed||null};});
    if(new Set(links.map(l=>l.activityId)).size!==links.length)throw Error('No repitas una actividad en los vínculos');
    const existing=state.restrictions.find(r=>r.id===id);if(existing?.released&&!yes('reopen'))throw Error('Reabre explícitamente una restricción liberada para cambiar sus condiciones');
    const entry={id:existing?.id||E.uid('R'),title:val('title'),category:val('category'),owner:val('owner'),estimated:val('estimated')||null,links,evidence:existing?.evidence||'',reviewer:existing?.reviewer||'',released:existing?.released||null};
    if(yes('reopen'))Object.assign(entry,{evidence:'',reviewer:'',released:null});if(existing)state.restrictions[state.restrictions.indexOf(existing)]=entry;else state.restrictions.push(entry);
   });break;
   case 'release':commit('Liberación documentada',id,()=>{
    const r=state.restrictions.find(r=>r.id===id);if(!yes('approved')||!E.validDate(val('released'))||val('released')>state.project.cut||!val('evidence')||!val('reviewer'))throw Error('Se necesita fecha real observada, evidencia y revisión confirmada');Object.assign(r,{released:val('released'),reviewer:val('reviewer'),evidence:val('evidence')});
   });break;
   case 'preparation':commit('Confirmación de preparación',id,()=>E.confirmPreparation(state,id,val('reviewer'),val('note')));break;
   case 'new-plan':commit('Nuevo plan semanal',val('start')+'–'+val('end'),()=>{chosenPlan=E.createPlan(state,val('start'),val('end')).id;});break;
   case 'commitment':commit('Compromiso semanal',val('activityId'),()=>{E.addCommitment(state,val('planId'),val('activityId'),number('target'),val('criterion'));chosenPlan=val('planId');});location.hash='semanal';break;
   case 'close-commitment':commit('Evaluación de compromiso',id,()=>E.closeCommitment(state,form.dataset.plan,id,val('result'),val('cause'),val('action'),yes('confirmed')));break;
   case 'milestone':commit('Hito observado',id,()=>E.recordMilestone(state,{activityId:id,date:val('date'),evidence:val('evidence'),reviewer:val('reviewer')}));break;
   case 'progress':commit('Avance observado',val('activityId')+' · '+val('quantity'),()=>E.recordProgress(state,{activityId:val('activityId'),date:val('date'),quantity:number('quantity'),reviewer:val('reviewer'),evidence:val('evidence'),accepted:yes('accepted')}));break;
   case 'interruption':commit('Interrupción observada',val('activityId')+' · '+val('cause'),()=>{if(val('end')<val('start')||val('end')>state.project.cut)throw Error('Revisa el intervalo observado');if(state.progress.some(p=>p.activityId===val('activityId')&&p.date>=val('start')&&p.date<=val('end')&&p.quantity>0))throw Error('El intervalo de días completos coincide con producción registrada; revisa las fechas');state.interruptions.push({id:E.uid('INT'),activityId:val('activityId'),start:val('start'),end:val('end'),cause:val('cause')});});break;
   case 'new-project':commit('Inicio de proyecto',val('name'),()=>{localStorage.setItem(ARCHIVE,JSON.stringify(state));state=E.emptyState();Object.assign(state.project,{name:val('name'),operator:val('operator'),origin:val('origin'),cut:E.addDays(val('origin'),-1)});});location.hash='datos';break;
  }
 }catch(e){toast(e.message,true);}
});
document.addEventListener('click',async event=>{
 const tab=event.target.closest('[data-data-tab]');if(tab){dataTab=tab.dataset.dataTab;render();return;}
 const advance=event.target.closest('[data-advance-tab]');if(advance){advanceTab=advance.dataset.advanceTab;render();return;}
 const target=event.target.closest('[data-action]');if(!target)return;const id=target.dataset.id;
 try{
  switch(target.dataset.action){
   case 'close':$('modal').close();break;
   case 'go-data':location.hash='datos';break;
   case 'activity':activityModal(id);break;
   case 'edit-activity':activityForm(id);break;
   case 'edit-measure':measureForm(id);break;
   case 'measure-index':measureForm('',Number(id));break;
   case 'restriction':if(!state.activities.length)throw Error('Carga primero el cronograma');restrictionForm('',id);break;
   case 'edit-restriction':restrictionForm(id);break;
   case 'release':releaseForm(id);break;
   case 'prepare':preparationForm(id);break;
   case 'new-plan':newPlanForm();break;
   case 'commitment':commitmentForm(id);break;
   case 'choose-commitment':commitmentForm();break;
   case 'freeze':if(confirm('¿Congelar los compromisos y las fechas de este corte? No podrás añadir o retirar miembros después.'))commit('Congelamiento de plan semanal',id,()=>E.freezePlan(state,id));break;
   case 'remove-commitment':commit('Retiro de compromiso del borrador',id,()=>{const p=selectedPlan();if(p.frozenAt)throw Error('El plan está congelado');p.members=p.members.filter(m=>m.activityId!==id);});break;
   case 'close-commitment':closeCommitmentForm(id);break;
   case 'progress':progressForm(id);break;
   case 'interruption':interruptionForm(id);break;
   case 'template-schedule':templates('schedule');break;
   case 'template-measures':templates('measures');break;
   case 'import-rates':if(!state.measures.length)throw Error('Importa primero los metrados del expediente');$('file-input').dataset.type='rates';$('file-input').accept='.csv';$('file-input').value='';$('file-input').click();break;
   case 'import-schedule':case 'import-measures':$('file-input').dataset.type=target.dataset.action==='import-schedule'?'schedule':'measures';$('file-input').accept=$('file-input').dataset.type==='schedule'?'.csv,.xlsx,.xml':'.csv,.xlsx';$('file-input').value='';$('file-input').click();break;
   case 'confirm-import':confirmImport();break;
   case 'backup':backup();break;
   case 'restore':modal('Recuperar un proyecto',`<p class="small muted">Un respaldo reemplaza el proyecto de este navegador. Primero se conservará el estado actual como versión anterior.</p><div class="actions">${button('choose-backup','Elegir archivo JSON','','button')}${button('previous','Recuperar proyecto anterior')}</div>`);break;
   case 'choose-backup':$('backup-input').value='';$('backup-input').click();break;
   case 'previous':{const saved=localStorage.getItem(ARCHIVE);if(!saved)throw Error('No hay una versión anterior guardada');const previous=E.validateBackup(JSON.parse(saved));if(confirm('¿Recuperar el proyecto anterior? El actual se conservará como versión anterior.'))commit('Recuperación local',previous.project.name,()=>{localStorage.setItem(ARCHIVE,JSON.stringify(state));state=previous;});break;}
   case 'new-project':modal('Comenzar un proyecto propio',`<form data-form="new-project"><p class="small muted">El proyecto actual se conservará como versión anterior local. También puedes exportarlo como JSON antes de continuar.</p><div class="form-grid">${field('Nombre del proyecto','name','','text','required')}${field('Responsable de los registros','operator','','text','required')}${field('Inicio del calendario de planificación','origin',state.project.origin,'date','required')}</div>${formEnd('Crear proyecto vacío')}</div>`);break;
   case 'export-report':{const p=selectedPlan(),k=E.indicators(state,p);download('pitocuna-reporte.csv',I.csv([['Proyecto',state.project.name],['Modo',state.project.mode],['Corte',state.project.cut],['Semana',p?.start||'',p?.end||''],['Congelada',p?.frozenAt||'No'],['PPC',k.ppc??'No aplica',k.fulfilled,k.committed],['PRL',k.prl??'No aplica',k.released,k.due],['Continuidad',k.continuity??'No aplica',k.programmed-k.interrupted,k.programmed],['Sin evaluar',k.pending],[],['Actividad','Ubicación','Alcance','Unidad','Criterio','Resultado','Causa','Acción'],...(p?.members||[]).map(m=>[m.activityId,m.location,m.target,m.unit,m.criterion,m.result,m.cause,m.action])]),'text/csv;charset=utf-8');break;}
  }
 }catch(e){toast(e.message,true);}
});
document.addEventListener('change',event=>{
 const el=event.target;
 try{
  if(el.id==='cut-date'){if(E.validDate(el.value))commit('Actualización del corte',el.value,()=>{state.project.cut=el.value;},false);else render();}
  if(el.id==='horizon'){weeks=Number(el.value);render();}
  if(el.id==='readiness-filter'){filterStatus=el.value;render();}
  if(el.id==='flow-group'){group=el.value;render();}
  if(el.id==='plan-select'){chosenPlan=el.value;render();}
  if(el.id==='progress-activity')$('progress-context').innerHTML=progressContext(el.value);
  if(el.id==='commitment-activity'){const a=state.activities.find(a=>a.id===el.value);el.form.elements.target.value=Math.max(0,E.measureOf(state,a).quantity-E.quantity(state,a.id));}
  if(el.id==='import-sheet'){pendingImport.sheet=Number(el.value);pendingImport.header=0;pendingImport.mapping=null;pendingImport.location=null;importPreview();}
  if(el.id==='import-location'){pendingImport.location=el.value;importPreview();}
  if(el.id==='import-header'){pendingImport.header=Number(el.value)-1;pendingImport.mapping=null;importPreview();}
  if(el.dataset.importField){pendingImport.mapping[el.dataset.importField]=Number(el.value);importPreview();}
 }catch(e){toast(e.message,true);}
});
$('file-input').addEventListener('change',async event=>{try{await readImport(event.target.files[0],event.target.dataset.type);}catch(e){toast(e.message,true);}});
$('backup-input').addEventListener('change',async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>12*1024*1024)throw Error('Respaldo demasiado grande');const incoming=E.validateBackup(JSON.parse(await file.text()));if(confirm('¿Restaurar '+incoming.project.name+'? El proyecto actual se conservará como versión anterior.'))commit('Restauración desde archivo',file.name,()=>{localStorage.setItem(ARCHIVE,JSON.stringify(state));state=incoming;});}catch(e){toast(e.message,true);}});
$('close-modal').addEventListener('click',()=>$('modal').close());
window.addEventListener('hashchange',render);
render();
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').then(reg=>reg.update()).catch(()=>{});
